3.1 🛠️ Yardımcı Fonksiyonlar


Kodu Göster / Gizle
bul_dosya &lt;- function(adaylar) {
  # Bu fonksiyon dosyayı yalnızca tek klasörde değil,
  # proje klasörü, QMD dosyasının klasörü ve üst klasörlerde arar.
  # Böylece Quarto başka yerden çalışsa bile data/ klasörünü bulma şansı artar.

  qmd_dizin &lt;- tryCatch(
    dirname(normalizePath(knitr::current_input(), winslash = "/", mustWork = FALSE)),
    error = function(e) NA_character_
  )

  baslangic_dizinleri &lt;- unique(na.omit(c(
    normalizePath(getwd(), winslash = "/", mustWork = FALSE),
    qmd_dizin
  )))

  # Başlangıç klasörleri + 5 seviye üst klasör
  kokler &lt;- unique(unlist(lapply(baslangic_dizinleri, function(d) {
    d &lt;- normalizePath(d, winslash = "/", mustWork = FALSE)
    ustler &lt;- d
    for (i in 1:5) {
      yeni &lt;- dirname(tail(ustler, 1))
      if (identical(yeni, tail(ustler, 1))) break
      ustler &lt;- c(ustler, yeni)
    }
    ustler
  })))

  olasi_yollar &lt;- unique(unlist(lapply(kokler, function(kok) {
    unlist(lapply(adaylar, function(ad) {
      c(
        file.path(kok, "data", ad),
        file.path(kok, ad)
      )
    }))
  })))

  bulunan &lt;- olasi_yollar[file.exists(olasi_yollar)]

  if (length(bulunan) == 0) {
    stop(
      paste0(
        "Dosya bulunamadı. Aranan adaylar: ",
        paste(adaylar, collapse = ", "),
        "\nÇalışma klasörü: ", getwd(),
        "\nQMD klasörü: ", qmd_dizin,
        "\nKontrol: data/ klasörü render edilen dosyayla aynı proje klasöründe olmalı."
      )
    )
  }

  normalizePath(bulunan[1], winslash = "/", mustWork = TRUE)
}

bul_dosya_opsiyonel &lt;- function(adaylar) {
  tryCatch(
    bul_dosya(adaylar),
    error = function(e) NA_character_
  )
}

hacim_sayi &lt;- function(x) {
  if (is.numeric(x)) {
    return(as.numeric(x))
  }

  x &lt;- as.character(x)
  x &lt;- str_squish(x)
  x &lt;- str_replace_all(x, "\\s", "")
  x &lt;- str_replace_all(x, "\\.", "")
  x &lt;- str_replace_all(x, ",", ".")
  as.numeric(x)
}

yuzde_sayi &lt;- function(x) {
  if (is.numeric(x)) {
    return(as.numeric(x))
  }

  x &lt;- as.character(x)
  x &lt;- str_squish(x)
  x &lt;- str_replace_all(x, "%", "")

  if_else(
    str_detect(x, ","),
    as.numeric(str_replace(str_replace_all(x, "\\.", ""), ",", ".")),
    as.numeric(x)
  )
}

